mapper.select:
SELECT DISTINCT m.person_id,o.id organization_id,o.name,CONCAT(o.type,' · ',o.id) distinguishing_label
FROM person_membership m JOIN person_organization o ON o.id=m.organization_id AND o.status='ACTIVE'
WHERE m.person_id IN #{p}
AND o.id IN #{o}
AND m.ended_event_id IS NULL AND m.valid_from<=#{at} AND (m.valid_until IS NULL OR m.valid_until>#{at}) ORDER BY m.person_id,o.id
